CREATE TYPE "InvitationStatus" AS ENUM ('DRAFT','READY','GENERATION_PENDING','GENERATING','GENERATED','FAILED','REVOKED');
CREATE TYPE "BatchStatus" AS ENUM ('RESERVING','QUEUED','GENERATING','COMPLETED','PARTIAL','FAILED','CANCELLED');
CREATE TYPE "BatchItemStatus" AS ENUM ('QUEUED','GENERATING','GENERATED','FAILED','CANCELLED');
CREATE TABLE "invitations" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"owner_subject" VARCHAR(255) NOT NULL,"event_id" UUID NOT NULL,"guest_id" UUID NOT NULL,"status" "InvitationStatus" NOT NULL DEFAULT 'DRAFT',"current_version_id" UUID,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "invitations_pkey" PRIMARY KEY ("id"),CONSTRAINT "invitations_event_id_guest_id_key" UNIQUE ("event_id","guest_id"));
CREATE INDEX "invitations_owner_subject_event_id_idx" ON "invitations"("owner_subject","event_id");
CREATE TABLE "invitation_versions" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"invitation_id" UUID NOT NULL,"version" INTEGER NOT NULL,"design_id" UUID NOT NULL,"design_version" INTEGER NOT NULL,"snapshot" JSONB NOT NULL,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "invitation_versions_pkey" PRIMARY KEY ("id"),CONSTRAINT "invitation_versions_invitation_id_fkey" FOREIGN KEY ("invitation_id") REFERENCES "invitations"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "invitation_versions_invitation_id_version_key" UNIQUE ("invitation_id","version"));
CREATE FUNCTION reject_invitation_version_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'invitation versions are immutable'; END; $$;
CREATE TRIGGER "invitation_versions_immutable" BEFORE UPDATE OR DELETE ON "invitation_versions" FOR EACH ROW EXECUTE FUNCTION reject_invitation_version_mutation();
CREATE TABLE "invitation_batches" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"owner_subject" VARCHAR(255) NOT NULL,"event_id" UUID NOT NULL,"design_id" UUID NOT NULL,"design_version" INTEGER NOT NULL,"status" "BatchStatus" NOT NULL DEFAULT 'RESERVING',"idempotency_key" VARCHAR(255) NOT NULL,"reservation_reference" VARCHAR(255) NOT NULL,"total_items" INTEGER NOT NULL,"completed_items" INTEGER NOT NULL DEFAULT 0,"failed_items" INTEGER NOT NULL DEFAULT 0,"cancelled_at" TIMESTAMPTZ(3),"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "invitation_batches_pkey" PRIMARY KEY ("id"),CONSTRAINT "invitation_batches_owner_idempotency_key" UNIQUE ("owner_subject","idempotency_key"),CONSTRAINT "invitation_batches_reservation_reference_key" UNIQUE ("reservation_reference"));
CREATE INDEX "invitation_batches_owner_created_idx" ON "invitation_batches"("owner_subject","created_at" DESC);
CREATE TABLE "invitation_batch_items" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"batch_id" UUID NOT NULL,"invitation_id" UUID NOT NULL,"guest_id" UUID NOT NULL,"snapshot" JSONB NOT NULL,"status" "BatchItemStatus" NOT NULL DEFAULT 'QUEUED',"object_key" VARCHAR(512),"error_code" VARCHAR(80),"attempts" INTEGER NOT NULL DEFAULT 0,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "invitation_batch_items_pkey" PRIMARY KEY ("id"),CONSTRAINT "invitation_batch_items_batch_id_fkey" FOREIGN KEY ("batch_id") REFERENCES "invitation_batches"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "invitation_batch_items_invitation_id_fkey" FOREIGN KEY ("invitation_id") REFERENCES "invitations"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "invitation_batch_items_batch_id_guest_id_key" UNIQUE ("batch_id","guest_id"));
CREATE INDEX "invitation_batch_items_batch_status_idx" ON "invitation_batch_items"("batch_id","status");
CREATE TABLE "outbox_messages" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"event_type" VARCHAR(100) NOT NULL,"aggregate_id" UUID NOT NULL,"payload" JSONB NOT NULL,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"published_at" TIMESTAMPTZ(3),"attempts" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "invitation_outbox_messages_pkey" PRIMARY KEY ("id"));
CREATE INDEX "invitation_outbox_pending_idx" ON "outbox_messages"("published_at","created_at");
